from pathlib import Path
import json, hashlib, re, sys

CID="AUTO-DISCOVERY-54d13314c7879b58e46d"
MODEL_TASK="A2Z-V4-ASTRA-POSTBUILD-20261006-R3-P2"
roots=[
 Path.home()/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4",
 Path.home()/".local/share/prediction-project-executor/worktrees/DEV-PRED-A2Z-POSTBUILD-RETRY-20261006-E106",
 Path.home()/".local/state/prediction-codex-supervisor",
]
MAX=2_000_000
records=[]

def sha256(p):
 try:
  return hashlib.sha256(p.read_bytes()).hexdigest()
 except Exception:
  return None

def walk(obj,path):
 if isinstance(obj,dict):
  dec=str(obj.get("decision","")).upper()
  blob=json.dumps(obj,sort_keys=True,default=str)
  if dec in {"APPROVE","NEEDS_REVISION","REVISE","REJECT","PARK"} and (
      MODEL_TASK in blob or CID in blob or "POSTBUILD" in blob.upper() or "postbuild" in path.lower()):
   records.append((path,obj))
  for v in obj.values(): walk(v,path)
 elif isinstance(obj,list):
  for v in obj: walk(v,path)

for root in roots:
 if not root.exists(): continue
 for p in root.rglob("*"):
  try:
   if not p.is_file() or p.stat().st_size>MAX: continue
  except OSError: continue
  if p.suffix.lower() not in {".json",".jsonl"}: continue
  try:
   raw=p.read_text(errors="replace")
  except Exception: continue
  low=raw.lower()
  if MODEL_TASK.lower() not in low and CID.lower() not in low and "postbuild" not in low:
   continue
  if p.suffix.lower()==".json":
   try: walk(json.loads(raw),str(p))
   except Exception: pass
  else:
   for line in raw.splitlines():
    try: walk(json.loads(line),str(p))
    except Exception: pass

# de-duplicate by path + stable object
uniq=[]
seen=set()
for path,d in records:
 key=(path,json.dumps(d,sort_keys=True,default=str))
 if key in seen: continue
 seen.add(key); uniq.append((path,d))

interesting=[
 "candidate_id","phase","review_phase","gate","decision",
 "reviewer_model","reviewer_model_slug","model","model_slug",
 "binding_sha256","review_binding_sha256","build_binding_sha256",
 "source_task_id","task_id","model_task_id","review_task_id",
 "provenance_kind","model_provenance_ref","model_provenance_sha256",
 "review_ref","ref","build_id","build_task_id","builder_model","builder_model_slug",
 "experiment_sha256","harness_sha256","code_sha256","worker_sha256",
]
out=[]
for path,d in uniq:
 item={"path":path,"keys":sorted(d.keys())}
 for k in interesting:
  if k in d: item[k]=d[k]
 # compact nested fields likely to contain bindings/provenance
 for k,v in d.items():
  lk=k.lower()
  if k in item: continue
  if any(x in lk for x in ("bind","proven","reviewer","build","hash","worker","model")):
   if isinstance(v,(str,int,float,bool)) or v is None:
    item[k]=v
   elif isinstance(v,dict):
    item[k]={kk:vv for kk,vv in v.items() if isinstance(vv,(str,int,float,bool)) or vv is None}
 out.append(item)

# resolve any referenced provenance files from review record roots and common worktree roots
refs=[]
for _,d in uniq:
 for k in ("model_provenance_ref","review_ref","ref"):
  v=d.get(k)
  if isinstance(v,str) and v and v not in refs: refs.append(v)

resolved=[]
for ref in refs:
 for root in roots:
  candidates=[root/ref]
  if "worktrees/" in str(root):
   candidates.append(root/ref.lstrip("/"))
  for p in candidates:
   if p.exists() and p.is_file():
    entry={"ref":ref,"path":str(p),"sha256":sha256(p)}
    try:
     obj=json.loads(p.read_text())
     entry["keys"]=sorted(obj.keys()) if isinstance(obj,dict) else []
     if isinstance(obj,dict):
      for k in interesting:
       if k in obj: entry[k]=obj[k]
    except Exception:
     pass
    resolved.append(entry)

summary={"record_count":len(out),"records":out,"resolved_refs":resolved}
print("E106_EVIDENCE_FORENSICS "+json.dumps(summary,separators=(",",":"),default=str),flush=True)
raise SystemExit(0)
